fn solve(n: i8) -> Vec<char> {
    // We only care about the ones digit of n.
    // Since n is in 1..=999, it is positive and n % 10 yields 0..=9.
    let ones = n % 10;

    // Map the ones digit to the correct suffix.
    let suffix = match ones {
        2 | 4 | 5 | 7 | 9 => "hon\n",
        0 | 1 | 6 | 8   => "pon\n",
        _               => "bon\n",  // only remaining case is 3
    };

    // Convert the &str suffix into a Vec<char> and return it.
    suffix.chars().collect()
}

